DO $agent_version_activation_schedules$ BEGIN
 IF to_regclass('public.platform_agent_version_reviews') IS NULL THEN RETURN; END IF;
 CREATE TABLE platform_agent_version_activation_schedules(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,owner_id VARCHAR(36) NOT NULL,agent_id VARCHAR(64) NOT NULL,agent_version_id UUID NOT NULL,config_hash VARCHAR(64) NOT NULL,review_id UUID NOT NULL,action VARCHAR(16) NOT NULL,expected_agent_revision BIGINT NOT NULL,expected_current_version_id UUID,state VARCHAR(16) NOT NULL,execute_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,claim_token UUID,claim_owner VARCHAR(120),lease_until TIMESTAMPTZ,fencing_token BIGINT NOT NULL DEFAULT 0,revision BIGINT NOT NULL,created_by VARCHAR(36) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,safe_error_code VARCHAR(64),CONSTRAINT fk_agent_activation_review FOREIGN KEY(review_id,tenant_id,agent_version_id,config_hash) REFERENCES platform_agent_version_reviews(id,tenant_id,agent_version_id,config_hash),CONSTRAINT fk_agent_activation_definition FOREIGN KEY(agent_id,tenant_id,owner_id) REFERENCES platform_agent_definitions(id,tenant_id,owner_id),CONSTRAINT fk_agent_activation_version FOREIGN KEY(agent_id,agent_version_id) REFERENCES platform_agent_versions(agent_id,id),CONSTRAINT fk_agent_activation_creator FOREIGN KEY(created_by,tenant_id) REFERENCES platform_users(id,tenant_id),CONSTRAINT uk_agent_activation_pending UNIQUE(agent_id,agent_version_id,action,execute_at),CONSTRAINT ck_agent_activation_action CHECK(action IN('ACTIVATE','DEPRECATE','ROLLBACK')),CONSTRAINT ck_agent_activation_state CHECK(state IN('SCHEDULED','CLAIMED','SUCCEEDED','FAILED','UNKNOWN','CANCELLED','EXPIRED')),CONSTRAINT ck_agent_activation_hash CHECK(config_hash~'^[0-9a-f]{64}$'),CONSTRAINT ck_agent_activation_bounds CHECK(expected_agent_revision>0 AND expires_at>execute_at AND fencing_token>=0 AND revision>0),CONSTRAINT ck_agent_activation_claim CHECK((state='CLAIMED' AND claim_token IS NOT NULL AND claim_owner IS NOT NULL AND lease_until IS NOT NULL) OR (state<>'CLAIMED' AND claim_token IS NULL AND claim_owner IS NULL AND lease_until IS NULL)),CONSTRAINT ck_agent_activation_terminal CHECK((state IN('SUCCEEDED','FAILED','UNKNOWN','CANCELLED','EXPIRED') AND completed_at IS NOT NULL) OR (state IN('SCHEDULED','CLAIMED') AND completed_at IS NULL)));
 CREATE INDEX idx_agent_activation_due ON platform_agent_version_activation_schedules(execute_at,id) WHERE state='SCHEDULED';
END $agent_version_activation_schedules$;
